import {holeState} from './bandon-model.js';
import {courses,loadCourse,routePosition} from './course-registry.js';
import {groupsAt,clock} from './play-model.js';
import {describeGroup,teeTime} from './group-context.js';
const $=id=>document.getElementById(id),L=window.L,course=courses.find(c=>c.id==='sawgrass'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
let hole=1,selected=8,data,map,imagery,paused=reduced.matches,elapsed=0,last=performance.now();
const markers=new Map(),routes=new Map();
function minute(){return (hole-1+.15+(elapsed/60000)%.7)*course.target/18;}
function update(){if(!data||!map)return;const minutes=minute(),groups=groupsAt(minutes,'normal',course.target),own=groups.find(g=>g.id===8),chosen=groups.find(g=>g.id===selected),context=describeGroup(chosen,groups,minutes,'normal',course.target);
 for(const g of groups){if(minutes<(g.id-8)*10)continue;const route=data.holes.find(h=>h.hole===g.hole),pos=routePosition(route.route,g.fraction);let marker=markers.get(g.id);if(!marker){marker=L.marker(pos,{icon:L.divIcon({className:'hero-tracking-icon',html:`<div class="hero-tracking-pin ${g.id===8?'you':''}"><b>${teeTime(g.id)}</b><small>HOLE ${g.hole}</small></div>`,iconSize:[35,26],iconAnchor:[17,13]}),title:teeTime(g.id)+' simulated tee-time group',keyboard:true}).on('click',()=>{selected=g.id;update();}).addTo(map);markers.set(g.id,marker);}else marker.setLatLng(pos);const el=marker.getElement()?.firstElementChild;if(el){el.classList.toggle('is-selected',selected===g.id);el.querySelector('small').textContent='HOLE '+g.hole;}}
 $('hero-group-label').textContent=teeTime(selected)+' TEE TIME';$('hero-group-activity').textContent=context.activity;$('hero-group-detail').textContent=`Hole ${context.hole} · ${context.pace.toLowerCase()}`;
 const remaining=Math.max(1,Math.ceil((1-own.fraction)*course.target/18));$('hero-eta').replaceChildren(document.createTextNode(remaining+' '),Object.assign(document.createElement('span'),{textContent:'min'}));$('watch-eta').textContent=remaining+' min';
 document.querySelectorAll('.phone-metrics>div:last-child>strong,.watch-footer>div:last-child>strong').forEach(el=>el.textContent=clock(510+course.target));
}
function selectHole(value){hole=value;elapsed=0;selected=8;for(const marker of markers.values())marker.remove();markers.clear();const state=holeState(hole,1,'sawgrass'),number=String(hole).padStart(2,'0');for(const id of ['hero-hole-number','watch-hole'])$(id).textContent=number;for(const id of ['hero-par','watch-par'])$(id).textContent=`PAR ${state.par}`;for(const id of ['hero-yards','watch-yards'])$(id).textContent=state.yards;document.querySelectorAll('[data-hero-hole]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.heroHole)===hole)));if(data){for(const [h,line] of routes)line.setStyle({color:h===hole?'#f1d189':'#faf4d4',weight:h===hole?3:1,opacity:h===hole?.95:.28});map.invalidateSize();map.fitBounds(data.holes.find(h=>h.hole===hole).route,{paddingTopLeft:[22,68],paddingBottomRight:[22,38],maxZoom:19,animate:false});update();}}
for(const button of document.querySelectorAll('[data-hero-hole]'))button.addEventListener('click',()=>selectHole(Number(button.dataset.heroHole)));
function renderPause(){$('hero-map-play').textContent=paused?'▷':'Ⅱ';$('hero-map-play').setAttribute('aria-label',paused?'Resume demo tracking':'Pause demo tracking');$('hero-map-play').setAttribute('aria-pressed',String(paused));}
$('hero-map-play').addEventListener('click',()=>{paused=!paused;renderPause();});renderPause();
if(L){loadCourse('sawgrass').then(c=>{data=c;map=L.map('hero-course-map',{zoomControl:false,scrollWheelZoom:false,dragging:true,touchZoom:true,maxZoom:19,minZoom:12,attributionControl:true});map.attributionControl.setPrefix('');map.attributionControl.addAttribution('&copy; <a href="https://www.openstreetmap.org/copyright">OSM</a>');const colors={fairway:'#8aa774',green:'#b2ca80',tee:'#98b57c',bunker:'#e2d4ab',sand:'#ded0a6',water:'#7da7a1',wood:'#81966d',forest:'#81966d',rough:'#a8b78a'};for(const f of data.terrain)L.polygon(f.points,{stroke:false,fillColor:colors[f.kind]||'#b9c49f',fillOpacity:.95,interactive:false}).addTo(map);imagery=L.tileLayer('https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryOnly/MapServer/tile/{z}/{y}/{x}',{maxNativeZoom:16,maxZoom:19,attribution:'USDA / USGS'}).on('tileerror',()=>{imagery.remove();$('hero-map-status').textContent='Course detail · aerial imagery unavailable';$('hero-map-status').hidden=false;}).addTo(map);for(const h of data.holes)routes.set(h.hole,L.polyline(h.route,{color:'#faf4d4',weight:1,opacity:.28,interactive:false}).addTo(map));$('hero-map-status').hidden=true;selectHole(1);new ResizeObserver(()=>map.invalidateSize()).observe($('hero-course-map'));}).catch(()=>{$('hero-map-status').textContent='Course map unavailable. Explore the courses below.';});}else $('hero-map-status').textContent='Course map unavailable. Explore the courses below.';
const timer=setInterval(()=>{const now=performance.now(),delta=Math.min(1000,now-last);last=now;if(paused||document.hidden||$('course-library').hidden)return;elapsed+=delta;update();},500);
window.addEventListener('pagehide',()=>clearInterval(timer));
